p='src/messaging/keys.ts'
s=open(p).read()
s=s.replace('import { OrderEventKind }','import { createHash } from "crypto";\nimport { OrderEventKind }',1)
s=s.replace('''  return `${namespace}.${KIND_CODE[kind]}.${orderNo}`;''','''  const logical = `${namespace}.${KIND_CODE[kind]}.${orderNo}`;
  // mqpub은 배치 안에서 키 앞 16바이트가 같으면 첫 메시지만 저장하므로,
  // 전체 논리 키의 결정적 해시(hex 16자)를 맨 앞에 둔다.
  const digest = createHash("sha256").update(logical).digest("hex").slice(0, 16);
  return `${digest}.${logical}`;''')
open(p,'w').write(s)
E
